// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class BlankNodeAllocationReferenceTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void labelledAllocationAvoidsKnownBindingIdentity() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		MapBindingSet bindings = new MapBindingSet();
		BNode fixed = VF.createBNode("label_1_0");
		bindings.addBinding("fixed", fixed);
		BNode allocated = context.getOrCreateBNode("label", bindings, VF);
		assertNotEquals(fixed, allocated, "fresh BNODE(label) must not alias an existing bound node");
		assertEquals(allocated, context.getOrCreateBNode("label", bindings, VF));
	}

	@Test
	void labelledAllocationRemembersEachSolutionIdentity() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		MapBindingSet first = new MapBindingSet();
		MapBindingSet second = new MapBindingSet();
		BNode a = context.getOrCreateBNode("label", first, VF);
		BNode b = context.getOrCreateBNode("label", second, VF);
		assertNotEquals(a, b);
		assertEquals(a, context.getOrCreateBNode("label", first, VF),
				"the same label in the same solution retains its value when another solution intervenes");
	}
}
